mapper.select:
SELECT id, emp_id AS empId, emp_team AS empTeam, emp_name AS empName, am_state AS amState, pm_state AS pmState, record_date AS recordDate, create_time AS createTime, update_time AS updateTime FROM fqc_attendance_record
AND emp_id = #{queryParams.empId}
AND emp_name LIKE CONCAT('%', #{queryParams.empName}, '%')
AND emp_team = #{queryParams.empTeam}
AND am_state = #{queryParams.amState}
AND pm_state = #{queryParams.pmState}
AND record_date = #{queryParams.recordDate}
ORDER BY record_date DESC, emp_team ASC, emp_name ASC
